mapper.select:
SELECT distinct t.id, t.user_id, t.work_date, t.company_id, t.schedule_id, t.overtime_reason, t.refuse_reason, t.approval_people_id, t.approval_status, b.first_start_time startTime, IFNULL( b.second_end_time, b.first_end_time ) endTime, TIMESTAMPDIFF(MINUTE,b.first_start_time,IFNULL( b.second_end_time, b.first_end_time )) workOverTime, b.name, t.crt_time, t.upd_time FROM work_overtime_info t LEFT JOIN base_schedule b ON t.schedule_id = b.id LEFT JOIN copy_info ci ON ci.apply_id = t.id and ci.apply_type = 1
and t.id = #{id}
and t.user_id = #{userId}
and t.approval_people_id = #{approvalPeopleId}
and t.approval_status = #{approvalStatus}
and t.approval_status in (1,2)
and ci.user_id = #{copyId}
and t.crt_time >= #{startTime} and t.crt_time <= #{endTime}
and t.user_id in
#{item}
order by t.crt_time desc

select t.id, t.user_id as userId, t.work_date as workDate, t.company_id as companyId, t.rest_schedule_id as restScheduleId, t.schedule_id as scheduleId, t.overtime_reason as overtimeReason, t.approval_people_id as approvalPeopleId, t.approval_status as approvalStatus, t.refuse_reason as refuseReason, t.crt_time as crtTime, bs.first_start_time as startTime, ifnull(bs.second_end_time,bs.first_end_time) as endTime from work_overtime_info t left join base_schedule bs on t.schedule_id=bs.id
and t.approval_status = #{queryForm.approvalStatus}
and t.user_id = #{queryForm.userId}
and t.company_id = #{queryForm.companyId}
and DATE_FORMAT(t.work_date,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.startTime},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.endTime},'%Y-%m-%d')
and t.id in
#{item}
order by t.crt_time desc

select t.id, t.work_date as workDate, t.company_id as companyId, t.rest_schedule_id as restScheduleId, t.schedule_id as scheduleId, t.approval_people_id as approvalPeopleId, t.approval_status as approvalStatus, t.crt_time as applyDate, bs.first_start_time as onPunchTime, ifnull(bs.second_end_time,bs.first_end_time) as offPunchTime, bs.name as scheduleName, mm.minute as markupMinute, mm.id as makeupId, mm.makeup_desc as makeupDesc from work_overtime_info t left join base_schedule bs on t.schedule_id=bs.id left join attendance_manual_makeup mm on (t.user_id=mm.user_id and t.company_id=mm.org_id and t.work_date=mm.makeup_date)
and t.approval_status = #{queryForm.approvalStatus}
and t.user_id = #{queryForm.userId}
and t.company_id = #{queryForm.companyId}
and DATE_FORMAT(t.work_date,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.startTime},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.endTime},'%Y-%m-%d')
order by t.crt_time desc
